CREATE OR REPLACE FUNCTION public.incrementar_tokens_proveedor(p_provider_id text, p_tokens integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_providers jsonb;
  v_actualizado jsonb := '[]'::jsonb;
  v_item jsonb;
BEGIN
  -- Leer el array actual
  SELECT valor INTO v_providers
  FROM configuraciones_sistema
  WHERE clave = 'ai_providers';

  IF v_providers IS NULL OR NOT jsonb_typeof(v_providers, 'array') THEN
    RETURN;
  END IF;

  -- Recorrer y actualizar el provider matching
  FOR v_item IN SELECT jsonb_array_elements(v_providers)
  LOOP
    IF v_item->>'id' = p_provider_id THEN
      v_actualizado := v_actualizado || jsonb_build_array(
        jsonb_set(
          jsonb_set(v_item, '{tokens_usados}', to_jsonb(
            COALESCE((v_item->>'tokens_usados')::integer, 0) + p_tokens
          )),
          '{tokens_updated_at}', to_jsonb(now()::text)
        )
      );
    ELSE
      v_actualizado := v_actualizado || jsonb_build_array(v_item);
    END IF;
  END LOOP;

  -- Actualizar el array completo
  UPDATE configuraciones_sistema
  SET valor = v_actualizado
  WHERE clave = 'ai_providers';
END;
$function$

CREATE OR REPLACE FUNCTION public.obtener_estadisticas_quejas()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  resultado JSON;
  v_total BIGINT;
  v_mes_actual BIGINT;
  v_resueltas_a_tiempo BIGINT;
  v_resueltas_total BIGINT;
  v_procedentes BIGINT;
  v_total_con_decision BIGINT;
BEGIN
  -- Total de quejas
  SELECT COUNT(*) INTO v_total FROM quejas;

  -- Quejas del mes actual
  SELECT COUNT(*) INTO v_mes_actual
  FROM quejas
  WHERE date_trunc('month', fecha) = date_trunc('month', CURRENT_DATE);

  -- Resueltas a tiempo (fecha_cierre <= fecha_sla)
  SELECT
    COUNT(*) FILTER (WHERE fecha_cierre IS NOT NULL AND fecha_sla IS NOT NULL AND fecha_cierre <= fecha_sla),
    COUNT(*) FILTER (WHERE fecha_cierre IS NOT NULL)
  INTO v_resueltas_a_tiempo, v_resueltas_total
  FROM quejas
  WHERE estado IN ('Resuelto', 'Finalizado');

  -- Tasa de procedencia
  SELECT
    COUNT(*) FILTER (WHERE estado NOT IN ('No Procede', 'Recibido')),
    COUNT(*) FILTER (WHERE estado != 'Recibido')
  INTO v_procedentes, v_total_con_decision
  FROM quejas;

  resultado := json_build_object(
    'total', v_total,
    'mes_actual', v_mes_actual,
    'resueltas_a_tiempo', v_resueltas_a_tiempo,
    'resueltas_total', v_resueltas_total,
    'pct_a_tiempo', CASE WHEN v_resueltas_total > 0 THEN ROUND((v_resueltas_a_tiempo::NUMERIC / v_resueltas_total) * 100, 1) ELSE 0 END,
    'procedentes', v_procedentes,
    'total_con_decision', v_total_con_decision,
    'pct_procedencia', CASE WHEN v_total_con_decision > 0 THEN ROUND((v_procedentes::NUMERIC / v_total_con_decision) * 100, 1) ELSE 0 END
  );

  RETURN resultado;
END;
$function$

CREATE OR REPLACE FUNCTION public.qms_publish_calendar(p_expected bigint, p_weekdays integer[], p_holidays jsonb, p_reason text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE previous qms_calendars; result bigint; h jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT app_es_admin() THEN RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('qms.config',0));
 SELECT * INTO previous FROM qms_calendars ORDER BY id DESC LIMIT 1;
 IF previous.id IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'El calendario cambió. Actualiza antes de guardar.' USING ERRCODE='40001'; END IF;
 IF p_weekdays IS NULL OR cardinality(p_weekdays) NOT BETWEEN 1 AND 7 OR NOT p_weekdays<@ARRAY[1,2,3,4,5,6,7]
 OR array_position(p_weekdays,NULL) IS NOT NULL OR cardinality(p_weekdays)<>(SELECT count(DISTINCT d) FROM unnest(p_weekdays) d)
 OR p_holidays IS NULL OR jsonb_typeof(p_holidays)<>'array' OR jsonb_array_length(p_holidays)>1000
 THEN RAISE EXCEPTION 'Calendario inválido' USING ERRCODE='22023'; END IF;
 FOR h IN SELECT * FROM jsonb_array_elements(p_holidays) LOOP
   IF coalesce(h->>'date','')!~'^\d{4}-\d{2}-\d{2}$' OR nullif(btrim(h->>'description'),'') IS NULL THEN RAISE EXCEPTION 'Cada feriado necesita fecha y descripción'; END IF;
   PERFORM (h->>'date')::date;
 END LOOP;
 IF (SELECT count(DISTINCT item->>'date') FROM jsonb_array_elements(p_holidays) item)<>jsonb_array_length(p_holidays) THEN RAISE EXCEPTION 'Hay feriados duplicados'; END IF;
 INSERT INTO qms_calendars(weekdays,holidays,created_by) VALUES(p_weekdays,p_holidays,app_usuario_actual_id()) RETURNING id INTO result;
 INSERT INTO qms_config_audit(entity,old_value,new_value,reason,actor_id)
 SELECT 'calendar',to_jsonb(previous),to_jsonb(c),p_reason,app_usuario_actual_id() FROM qms_calendars c WHERE id=result;
 RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION public.qms_publish_stage(p_stage text, p_expected bigint, p_duration integer, p_type text, p_alerts integer[], p_action text, p_reason text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE previous qms_stage_versions; result bigint;
BEGIN
 IF auth.uid() IS NULL OR NOT app_es_admin() THEN RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('qms.config',0));
 SELECT * INTO previous FROM qms_stage_versions WHERE stage_id=p_stage ORDER BY id DESC LIMIT 1;
 IF previous.id IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'La configuración cambió. Actualiza antes de guardar.' USING ERRCODE='40001'; END IF;
 IF p_duration IS NULL OR p_duration NOT BETWEEN 1 AND 3660 OR p_type IS NULL OR p_type NOT IN ('business_days','calendar_days')
 OR p_action IS NULL OR p_action NOT IN ('notify_quality','mark_only') OR p_alerts IS NULL
 OR EXISTS(SELECT 1 FROM unnest(p_alerts) a WHERE a IS NULL OR a<1 OR a>p_duration)
 OR cardinality(p_alerts)<>(SELECT count(DISTINCT a) FROM unnest(p_alerts) a)
 THEN RAISE EXCEPTION 'Revisa duración, tipo de días, acción y alertas: positivas, únicas y dentro del plazo.' USING ERRCODE='22023'; END IF;
 INSERT INTO qms_stage_versions(stage_id,duration,day_type,alerts,expiration_action,created_by)
 VALUES(p_stage,p_duration,p_type,p_alerts,p_action,app_usuario_actual_id()) RETURNING id INTO result;
 INSERT INTO qms_config_audit(entity,old_value,new_value,reason,actor_id)
 SELECT p_stage,to_jsonb(previous),to_jsonb(v),p_reason,app_usuario_actual_id() FROM qms_stage_versions v WHERE id=result;
 RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION public.qms_transition(p_id uuid, p_expected bigint, p_state text, p_resolution text DEFAULT NULL::text, p_justification text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid, p_reopen text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE q quejas; target text;
BEGIN
 SELECT * INTO q FROM quejas WHERE id=p_id FOR UPDATE;
 IF auth.uid() IS NULL OR NOT (coalesce(app_es_staff(),false) OR (coalesce(app_es_colaborador(),false) AND coalesce(q.responsable_id=app_usuario_actual_id(),false))) THEN RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF;
 IF q.id IS NULL THEN RAISE EXCEPTION 'Queja no encontrada'; END IF;
 IF p_expected IS NULL OR q.revision<>p_expected THEN RAISE EXCEPTION 'Otra persona modificó la queja. Actualiza el expediente antes de guardar.' USING ERRCODE='40001'; END IF;
 SELECT valor_interno INTO target FROM catalogos WHERE modulo='quejas' AND tipo='estado_queja' AND codigo=p_state LIMIT 1;
 IF target IS NULL THEN RAISE EXCEPTION 'Estado no reconocido'; END IF;
 IF q.estado='Recibido' AND target='En Investigación' AND
 (nullif(btrim(p_justification),'') IS NULL OR coalesce(p_owner,q.responsable_id) IS NULL) THEN RAISE EXCEPTION 'Selecciona un responsable y escribe la justificación'; END IF;
 PERFORM public.transicionar_queja(p_id,target,p_resolution,p_justification,p_owner,p_reopen);
 RETURN (SELECT to_jsonb(v) FROM qms_quejas v WHERE id=p_id);
END; $function$

CREATE OR REPLACE FUNCTION public.qms_update_details(p_id uuid, p_expected bigint, p_categoria text DEFAULT NULL::text, p_prioridad text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE q quejas;
BEGIN
 IF auth.uid() IS NULL OR NOT app_es_staff() THEN RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF;
 SELECT * INTO q FROM quejas WHERE id=p_id FOR UPDATE;
 IF p_expected IS NULL OR q.revision IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'Otra persona modificó la queja. Actualiza antes de guardar.' USING ERRCODE='40001'; END IF;
 PERFORM public.actualizar_detalles_queja(p_id,p_categoria,p_prioridad,p_owner,p_notes);
 RETURN (SELECT to_jsonb(v) FROM qms_quejas v WHERE id=p_id);
END; $function$

CREATE OR REPLACE FUNCTION public.registrar_adjunto_queja(p_queja_id uuid, p_nombre text, p_storage_path text, p_tamano bigint DEFAULT 0, p_tipo_mime text DEFAULT 'application/octet-stream'::text)
 RETURNS queja_adjuntos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_adjunto   public.queja_adjuntos;
  v_usuario_id uuid;
BEGIN
  v_usuario_id := public.app_usuario_actual_id();
  IF v_usuario_id IS NULL THEN RAISE EXCEPTION 'No autorizado'; END IF;

  IF NOT public.app_es_staff() AND NOT (
    public.app_es_colaborador()
    AND EXISTS (
      SELECT 1 FROM public.quejas q
      WHERE q.id = p_queja_id AND q.responsable_id = v_usuario_id
    )
  ) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  IF btrim(COALESCE(p_nombre, '')) = '' OR btrim(COALESCE(p_storage_path, '')) = '' THEN
    RAISE EXCEPTION 'Nombre y ruta del adjunto son obligatorios';
  END IF;

  INSERT INTO public.queja_adjuntos (
    queja_id,
    nombre,
    nombre_archivo,
    storage_path,
    url_archivo,
    tamano,
    tipo_mime,
    usuario_id,
    created_at
  ) VALUES (
    p_queja_id,
    btrim(p_nombre),
    btrim(p_nombre),
    btrim(p_storage_path),
    btrim(p_storage_path),
    COALESCE(p_tamano, 0),
    COALESCE(nullif(btrim(COALESCE(p_tipo_mime, '')), ''), 'application/octet-stream'),
    v_usuario_id,
    now()
  )
  RETURNING * INTO v_adjunto;

  INSERT INTO public.logs (fecha, usuario_id, accion, modulo, detalle)
  VALUES (now(), v_usuario_id, 'adjunto', 'quejas',
    'Adjunto "' || v_adjunto.nombre || '" agregado a la queja ' || p_queja_id);

  RETURN v_adjunto;
END;
$function$

CREATE OR REPLACE FUNCTION public.transicionar_queja(p_queja_id uuid, p_nuevo_estado text, p_resolucion text DEFAULT NULL::text, p_justificacion_procede text DEFAULT NULL::text, p_responsable_id uuid DEFAULT NULL::uuid, p_motivo_reapertura text DEFAULT NULL::text)
 RETURNS quejas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_queja          public.quejas;
  v_usuario_id     uuid;
  v_es_staff       boolean;
  v_es_responsable boolean;
  v_destino        record;
  v_mensaje        text;
BEGIN
  v_usuario_id := public.app_usuario_actual_id();
  IF v_usuario_id IS NULL THEN RAISE EXCEPTION 'No autorizado'; END IF;

  SELECT * INTO v_queja FROM public.quejas WHERE id = p_queja_id FOR UPDATE;
  IF v_queja.id IS NULL THEN RAISE EXCEPTION 'Queja no encontrada'; END IF;

  v_es_staff := public.app_es_staff();
  v_es_responsable := (v_queja.responsable_id = v_usuario_id);
  IF NOT (v_es_staff OR (public.app_es_colaborador() AND v_es_responsable)) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  IF v_queja.estado = 'Recibido' AND p_nuevo_estado = 'En Investigación' THEN
    IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede iniciar la investigación'; END IF;
    UPDATE public.quejas
    SET estado = p_nuevo_estado,
        fecha_limite_investigacion = now() + interval '15 days',
        responsable_id = COALESCE(p_responsable_id, responsable_id),
        notas = CASE WHEN btrim(COALESCE(p_justificacion_procede, '')) <> ''
          THEN COALESCE(notas, '') || E'\n[Procede] ' || btrim(p_justificacion_procede)
          ELSE notas END
    WHERE id = p_queja_id RETURNING * INTO v_queja;

  ELSIF v_queja.estado = 'Recibido' AND p_nuevo_estado = 'No Procede' AND btrim(COALESCE(p_resolucion, '')) <> '' THEN
    IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede marcar como No Procede'; END IF;
    UPDATE public.quejas SET estado = p_nuevo_estado, resolucion = btrim(p_resolucion), fecha_cierre = now()
    WHERE id = p_queja_id RETURNING * INTO v_queja;

  ELSIF v_queja.estado = 'En Investigación' AND p_nuevo_estado = 'Pendiente de Revisión GC' AND btrim(COALESCE(p_resolucion, '')) <> '' THEN
    UPDATE public.quejas SET estado = p_nuevo_estado, resolucion = btrim(p_resolucion)
    WHERE id = p_queja_id RETURNING * INTO v_queja;

  ELSIF v_queja.estado = 'En Investigación' AND p_nuevo_estado = 'Resuelto' AND btrim(COALESCE(p_resolucion, '')) <> '' THEN
    IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede resolver directamente'; END IF;
    UPDATE public.quejas SET estado = p_nuevo_estado, resolucion = btrim(p_resolucion)
    WHERE id = p_queja_id RETURNING * INTO v_queja;

  ELSIF v_queja.estado = 'Pendiente de Revisión GC' AND p_nuevo_estado = 'Resuelto' THEN
    IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede aprobar la resolución'; END IF;
    UPDATE public.quejas SET estado = p_nuevo_estado, fecha_cierre = COALESCE(fecha_cierre, now())
    WHERE id = p_queja_id RETURNING * INTO v_queja;

  ELSIF v_queja.estado = 'Pendiente de Revisión GC' AND p_nuevo_estado = 'En Investigación' THEN
    IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede devolver la queja'; END IF;
    UPDATE public.quejas SET estado = p_nuevo_estado, resolucion = NULL
    WHERE id = p_queja_id RETURNING * INTO v_queja;

  ELSIF v_queja.estado = 'Resuelto' AND p_nuevo_estado = 'Finalizado' THEN
    IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede finalizar la queja'; END IF;
    UPDATE public.quejas SET estado = p_nuevo_estado, fecha_cierre = COALESCE(fecha_cierre, now())
    WHERE id = p_queja_id RETURNING * INTO v_queja;

  ELSIF v_queja.estado IN ('Resuelto', 'Finalizado') AND p_nuevo_estado = 'En Investigación' AND btrim(COALESCE(p_motivo_reapertura, '')) <> '' THEN
    IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede reabrir la queja'; END IF;
    UPDATE public.quejas
    SET estado = 'En Investigación',
        fecha_limite_investigacion = now() + interval '15 days',
        resolucion = NULL,
        notas = COALESCE(notas, '') || E'\n[Reapertura] ' || btrim(p_motivo_reapertura)
    WHERE id = p_queja_id RETURNING * INTO v_queja;

  ELSE
    RAISE EXCEPTION 'Transición no permitida: % → %', v_queja.estado, p_nuevo_estado;
  END IF;

  v_mensaje := 'La queja ' || v_queja.folio || ' cambió a ' || v_queja.estado || '.';
  FOR v_destino IN
    SELECT id FROM public.usuarios
    WHERE (id = v_queja.responsable_id OR rol IN ('admin', 'calidad'))
      AND estado = 'activo'
      AND id IS DISTINCT FROM v_usuario_id
  LOOP
    INSERT INTO public.notificaciones (usuario_id, fecha, tipo, mensaje, enlace, origen_id)
    VALUES (v_destino.id, now(), 'queja_estado', v_mensaje, '/quejas', v_queja.id);
  END LOOP;

  INSERT INTO public.logs (fecha, usuario_id, accion, modulo, detalle)
  VALUES (now(), v_usuario_id, 'transición', 'quejas', v_mensaje);
  RETURN v_queja;
END;
